/bin/zsh -lc "python3 -B -c 'import csv,collections; from pathlib import Path; p=Path(\"atlas/v4/paired_observations.csv\"); f=p.open(newline=\"\"); reader=csv.DictReader(f); print(\"SCHEMA:\",reader.fieldnames); rows=[{k:v for k,v in r.items() if k in (\"gene\",\"axis\",\"model\",\"held_condition\")} for r in reader]; counts=collections.Counter((r[\"model\"],r[\"axis\"]) for r in rows); keys=collections.Counter(tuple(r[k] for k in (\"gene\",\"axis\",\"model\",\"held_condition\")) for r in rows); print(\"ROWS:\",len(rows)); print(\"STRATUM_COUNTS:\",sorted(counts.items())); print(\"UNIQUE_KEYS:\",len(keys)); print(\"DUPLICATE_KEYS:\",sum(v>1 for v in keys.values())); print(\"MISSING_KEY_FIELDS:\",sum(any(r.get(k) in (None,\"\") for k in (\"gene\",\"axis\",\"model\",\"held_condition\")) for r in rows));
