 subset=[r for r in rows if (r[\"model\"],r[\"axis\"])==stratum]; genes=sorted({r[\"gene\"] for r in subset}); folds={g:i%5 for i,g in enumerate(genes)}; targets=[sum(folds[r[\"gene\"]]==fold for r in subset) for fold in range(5)]; print(\"EPISODE_COUNTS:\",stratum,\"genes\",len(genes),\"targets\",targets,\"queries\",[len(subset)-n for n in targets])'"

